        assert.equal(result.success, true);
        assert.equal(loaded.createdTickets.length, 1, 'one subtask created');
        assert.equal(loaded.createdTickets[0].fieldsJson.summary.indexOf('[Q]'), 0, 'summary prefixed with [Q]');
