/**
 * Create Questions and Assign For Review Post-Action
 * Reads AI-generated outputs/questions.json, creates question subtasks in Jira,
 * labels the parent ticket, and assigns it for review.
 *
 * questions.json format:
 * [
 *   {
 *     "summary": "Clarify requirements",          // [Q] prefix added automatically if missing
 *     "priority": "High",
 *     "description": "outputs/questions/question-1.md",
 *     "answer": "..."                              // optional, pre-filled answer
 *   }
 * ]
 */

const { extractTicketKey } = require('./common/jiraHelpers.js');
const { buildSummary } = require('./common/aiResponseParser.js');
const configLoader = require('./configLoader.js');
const scmModule = require('./common/scm.js');
const autoStart = require('./common/autoStart.js');
const tokenUsageComment = require('./common/tokenUsageComment.js');
const outputFiles = require('./common/outputFiles.js');

// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var trackersModule = require('./common/trackers.js');
var _trackerCtx = { config: null, customParams: {} };
var _trackerInst = null;
function initTracker(config, customParams) {
    _trackerCtx = { config: config || null, customParams: customParams || {} };
    _trackerInst = null;
}
function getTracker() {
    if (!_trackerInst) _trackerInst = trackersModule.createTracker(_trackerCtx.config, _trackerCtx.customParams);
    return _trackerInst;
}

/**
 * Ensure summary starts with [Q] prefix
 */
function ensureQPrefix(summary) {
    if (!summary || summary.indexOf('[Q]') === 0) {
        return summary;
    }
    return '[Q] ' + summary;
}

/**
 * Read and parse outputs/questions.json
 * @returns {Array} Array of question entries, or empty array on error
 */
function readQuestionsJson() {
    try {
        var raw = file_read('outputs/questions.json');
        if (!raw || raw.trim() === '') {
            console.warn('outputs/questions.json is empty');
            return [];
        }
        var parsed = JSON.parse(raw);
        // Handle both plain array [...] and wrapped {"questions": [...]} formats
        if (!Array.isArray(parsed)) {
            if (parsed && Array.isArray(parsed.questions)) {
                console.warn('outputs/questions.json was wrapped in {"questions":[...]} — using inner array. Agent should write a plain JSON array.');
                return parsed.questions;
            }
            console.warn('outputs/questions.json is not an array');
            return [];
        }
        return parsed;
    } catch (error) {
        console.error('Failed to read/parse outputs/questions.json:', error);
        return [];
    }
}

/**
 * Read a description file, falling back to the entry summary
 */
function readDescriptionFile(filePath, fallbackSummary) {
    if (!filePath) {
        return fallbackSummary || '';
    }
    try {
        var content = file_read(filePath);
        if (content && content.trim() !== '') {
            return content;
        }
    } catch (error) {
        console.warn('Could not read description file ' + filePath + ':', error);
    }
    return fallbackSummary || '';
}

/**
 * When the agent decides no clarifying questions are needed, it must still
 * explain why in outputs/response.md. Post that explanation as a Jira comment
 * so a human reviewer sees the reasoning instead of a silent skip.
 * If the agent did NOT write a response.md, post a visible warning instead of
 * silently moving the ticket forward with zero explanation.
 */
function postNoQuestionsExplanation(ticketKey) {
    var explanation = outputFiles.readOutputFile('response.md', { ticketKey: ticketKey });
    if (explanation && explanation.trim()) {
        try {
            getTracker().postComment(ticketKey, 'h3. \u2139\ufe0f No clarifying questions needed\n\n' + explanation.trim());
            console.log('Posted no-questions explanation from outputs/response.md');
        } catch (e) {
            console.warn('Failed to post no-questions explanation comment:', e);
        }
        return;
    }

    console.warn('No questions were raised AND outputs/response.md is missing/empty — posting fallback warning comment.');
    try {
        getTracker().postComment(ticketKey, 'h3. \u26a0\ufe0f No clarifying questions raised \u2014 no explanation provided\n\n' +
                'The AI agent did not create any clarifying questions for this ticket, and did not write ' +
                '{{outputs/response.md}} explaining why. Please verify manually whether the story is actually ' +
                'clear enough to proceed, or re-run the agent.');
    } catch (e) {
        console.warn('Failed to post fallback no-questions warning comment:', e);
    }
}

/**
 * Create a single question subtask in Jira
 * @param {Object} entry - Entry from questions.json
 * @param {string} parentKey - Parent story ticket key
 * @param {string} projectKey - Jira project key
 * @param {Object} jiraConfig - Resolved jira config (issueTypes, labels, questions)
 * @param {Object} [priorityMap] - Optional mapping of agent priority names to project-specific names
 * @returns {string|null} Created ticket key or null on failure
 */
function createQuestion(entry, parentKey, projectKey, jiraConfig, priorityMap) {
    var summary = ensureQPrefix(buildSummary(entry.summary, 0));
    var description = readDescriptionFile(entry.description, entry.summary);
    var questionIssueType = jiraConfig.issueTypes.SUBTASK;
    var questionLabel = jiraConfig.labels.QUESTION;
    var answerField = jiraConfig.questions.answerField;

    var fieldsJson = {
        summary: summary,
        description: description,
        issuetype: { name: questionIssueType },
        parent: { key: parentKey },
        labels: [questionLabel]
    };

    if (entry.priority) {
        var resolvedPriority = (priorityMap && priorityMap[entry.priority]) || entry.priority;
        fieldsJson.priority = { name: resolvedPriority };
    }

    if (entry.answer) {
        fieldsJson[answerField] = entry.answer;
    }

    try {
        var tracker = getTracker();
        var result;
        if (tracker.provider() === 'ado') {
            // agents#870: fieldsJson above is Jira-shaped (issuetype/parent/summary); createTicketWithFields on
            // ADO needs ADO field names and would throw. Create the work item, link it to its parent and add
            // the question label through the tracker instead. The work item type is jira.questions.workItemType
            // (default 'Task' — the child type of a PBI/Bug in the standard ADO processes).
            var adoType = (jiraConfig.questions && jiraConfig.questions.workItemType) || 'Task';
            result = tracker.createTicketWithParent(projectKey, adoType, summary, description, parentKey, { labels: [questionLabel] });
            if (result && entry.priority) {
                try {
                    tracker.setPriority(result, (priorityMap && priorityMap[entry.priority]) || entry.priority);
                } catch (priorityError) {
                    console.warn('Could not set priority on question ' + result + ' (non-fatal):', priorityError);
                }
            }
        } else {
            result = tracker.createTicketWithFields(projectKey, fieldsJson);
        }
        var key = (typeof result === 'string' && result) ? result : extractTicketKey(result);
        console.log('Created question subtask ' + (key || '(unknown key)') + ': ' + summary);
        return key;
    } catch (error) {
        console.error('Failed to create question subtask "' + summary + '":', error);
        return null;
    }
}

function action(params) {
    try {
        var ticketKey = params.ticket.key;
        var projectKey = ticketKey.split('-')[0];
        initTracker(null, (params.jobParams && params.jobParams.customParams) || {});
        var initiatorId = params.initiator;
        var wipLabel = params.metadata && params.metadata.contextId
            ? params.metadata.contextId + '_wip'
            : null;

        // The CLI/AI-provider call can fail (missing binary, provider outage, HTTP 5xx, ...)
        // while outputType is 'none' a…

/**
 * Fetch Linked Test Cases To Input
 * Fetches linked Test Case tickets (with their comments/failure details) for
 * the current bug ticket and writes them to input/{KEY}/linked_tests.md.
 *
 * Used by: preCliDevelopmentSetup.js (before CLI bug development agent runs)
 *
 * WHY: When a bug is created from a failing automated test, the bug fix agent
 * needs to understand the EXACT test assertions and what the test expects.
 * This prevents "already fixed" false-positives where the code change is
 * present but the test still fails because the fix doesn't match test assumptions.
 * It also surfaces prior fix attempts visible in the test case comments.
 */


// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var trackersModule = require('./common/trackers.js');
var _trackerCtx = { config: null, customParams: {} };
var _trackerInst = null;
function initTracker(config, customParams) {
    _trackerCtx = { config: config || null, customParams: customParams || {} };
    _trackerInst = null;
}
function getTracker() {
    if (!_trackerInst) _trackerInst = trackersModule.createTracker(_trackerCtx.config, _trackerCtx.customParams);
    return _trackerInst;
}

function action(params) {
    try {
        var actualParams = params.inputFolderPath ? params : (params.jobParams || params);
        var folder = actualParams.inputFolderPath;
        initTracker(null, (params.jobParams && params.jobParams.customParams) || actualParams.customParams || {});
        var ticketKey = folder.split('/').pop();

        console.log('Fetching linked test cases for', ticketKey, '...');

        var linkedTests = [];
        try {
            // JQL text: provider-specific query (WIQL on ado)
            linkedTests = getTracker().searchIssues('issue in linkedIssues("' + ticketKey + '") AND issuetype = "Test Case"', { maxResults: 10, fields: ['key', 'summary', 'status', 'description', 'labels'] });
        } catch (e) {
            console.warn('Could not fetch linked test cases (skipping):', e);
            return;
        }

        if (!linkedTests || linkedTests.length === 0) {
            console.log('No linked test cases found for', ticketKey);
            return;
        }

        console.log('Found', linkedTests.length, 'linked test case(s) — fetching details...');

        var lines = [];
        lines.push('# Linked Test Cases\n');
        lines.push('> **IMPORTANT**: These test cases are linked to this bug (they failed and triggered this bug report).');
        lines.push('> Read the test steps and failure comments carefully.');
        lines.push('> Your fix MUST make these tests pass — "already fixed" is only valid if the test can actually pass with the current code.\n');

        for (var i = 0; i < linkedTests.length; i++) {
            var tc = linkedTests[i];
            var f = tc.fields || {};
            var status = (f.status && f.status.name) || 'Unknown';

            lines.push('---\n');
            lines.push('## ' + tc.key + ': ' + (f.summary || '(no summary)'));
            lines.push('**Status**: ' + status + '\n');

            if (f.description) {
                lines.push('**Test Case Description**:\n' + f.description + '\n');
            }

            // Fetch full ticket to get comments (test run history, failure details, prior attempts)
            try {
                var tcDetails = getTracker().getIssue(tc.key);
                var tcFields = tcDetails && tcDetails.fields || {};
                var commentBlock = tcFields.comment;
                var comments = commentBlock && commentBlock.comments || [];

                if (comments.length > 0) {
                    // Include up to last 5 comments (most recent test run results)
                    var startIdx = Math.max(0, comments.length - 5);
                    lines.push('**Test Run Comments (' + (comments.length - startIdx) + ' most recent)**:\n');
                    for (var j = startIdx; j < comments.length; j++) {
                        var c = comments[j];
                        var author = (c.author && c.author.displayName) || 'Unknown';
                        var body = (c.body || '').substring(0, 2000);
                        lines.push('**[' + author + ']**:');
                        lines.push(body);
                        lines.push('');
                    }
                }
            } catch (ce) {
                console.warn('Could not fetch comments for', tc.key, ':', ce);
            }
        }

        var content = lines.join('\n');

        try {
            file_write(folder + '/linked_tests.md', content);
            console.log('✅ Written linked_tests.md for', ticketKey, '(' + linkedTests.length + ' test(s))');
        } catch (we) {
            console.warn('Could not write linked_tests.md:', we);
        }

    } catch (error) {
        console.error('Error in fetchLinkedTestsToInput:', error);
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

/**
 * Fetch Linked Bugs To Input
 * Fetches linked bugs (with their comments) for the current ticket
 * and writes them to input/{KEY}/linked_bugs.md.
 *
 * Used by: preCliTestAutomationSetup.js (before CLI test automation runs)
 *
 * WHY: When a bug is fixed and the test re-runs, the test agent needs to know
 * HOW the bug was fixed (e.g., a heartbeat probe with a timing delay) so the
 * test properly accounts for implementation details like async delays.
 * Without this context, the test may assert too early and fail again,
 * creating a new bug → infinite loop.
 */

var trackersModule = require('./common/trackers.js');

function action(params) {
    try {
        var actualParams = params.inputFolderPath ? params : (params.jobParams || params);
        var folder = actualParams.inputFolderPath;
        var ticketKey = folder.split('/').pop();
        var tracker = trackersModule.createTracker(null, actualParams.customParams || (params.jobParams && params.jobParams.customParams) || {});

        console.log('Fetching linked bugs for', ticketKey, '...');

        var linkedBugs = [];
        try {
            linkedBugs = tracker.searchIssues('issue in linkedIssues("' + ticketKey + '") AND issuetype = Bug AND status not in (Done)', {
                fields: ['key', 'summary', 'status', 'description', 'Solution', 'labels'],
                maxResults: 10
            });
        } catch (e) {
            console.warn('Could not fetch linked bugs (skipping):', e);
            return;
        }

        if (!linkedBugs || linkedBugs.length === 0) {
            console.log('No linked bugs found for', ticketKey);
            return;
        }

        console.log('Found', linkedBugs.length, 'linked bug(s) — fetching details...');

        var lines = [];
        lines.push('# Linked Bugs\n');
        lines.push('> **CRITICAL FOR TEST IMPLEMENTATION**: These bugs are linked to this test case.');
        lines.push('> The test MUST account for any implementation details in the fix (timing delays, async behavior, retry intervals, etc.)');
        lines.push('> Read the Solution and AI Fix Comments carefully before writing or updating the test.\n');

        for (var i = 0; i < linkedBugs.length; i++) {
            var bug = linkedBugs[i];
            var f = bug.fields || {};
            var status = (f.status && f.status.name) || 'Unknown';

            lines.push('---\n');
            lines.push('## ' + bug.key + ': ' + (f.summary || '(no summary)'));
            lines.push('**Status**: ' + status + '\n');

            if (f.description) {
                lines.push('**Description**:\n' + f.description + '\n');
            }

            if (f.Solution) {
                lines.push('**Solution / Root Cause Analysis**:\n' + f.Solution + '\n');
            }

            // Fetch full ticket to get comments (especially the AI fix comment)
            try {
                var bugDetails = tracker.getIssue(bug.key);
                var bugFields = bugDetails && bugDetails.fields || {};
                var commentBlock = bugFields.comment;
                var comments = commentBlock && commentBlock.comments || [];

                if (comments.length > 0) {
                    // Include up to last 5 comments (most recent fix attempts)
                    var startIdx = Math.max(0, comments.length - 5);
                    lines.push('**Comments (' + (comments.length - startIdx) + ' most recent)**:\n');
                    for (var j = startIdx; j < comments.length; j++) {
                        var c = comments[j];
                        var author = (c.author && c.author.displayName) || 'Unknown';
                        var body = (c.body || '').substring(0, 2000);
                        lines.push('**[' + author + ']**:');
                        lines.push(body);
                        lines.push('');
                    }
                }
            } catch (ce) {
                console.warn('Could not fetch comments for', bug.key, ':', ce);
            }
        }

        var content = lines.join('\n');

        try {
            file_write(folder + '/linked_bugs.md', content);
            console.log('✅ Written linked_bugs.md for', ticketKey, '(' + linkedBugs.length + ' bug(s))');
        } catch (we) {
            console.warn('Could not write linked_bugs.md:', we);
        }

    } catch (error) {
        console.error('Error in fetchLinkedBugsToInput:', error);
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

