        assert.deepEqual(mod.buildRecentCommentLines(null, '**Comments'), []);
    });

    test('up to 5 comments: full list with count header', function () {
        var lines = loadReport().buildRecentCommentLines([c('A', 'one'), c('B', 'two')], '**Comments');
