        six.push(comment(undefined, undefined)); // missing author + body → Unknown / ''
        var longBody = '';
        for (var j = 0; j < 250; j++) longBody += 'x';
        six.push(comment('Verbose', longBody));

        var env = makeMocks({
            searchResult: [
                jiraIssue('TC-1', 'Login works', 'Failed', { description: 'Steps to reproduce' }),
                jiraIssue('TC-2', 'Logout works') // no status, no description
