        assert.contains(md, '**Test Case Description**:\nSteps to reproduce');
        assert.notContains(md, '## TC-2: Logout works\n**Status**: Unknown\n\n**Test Case Description**');
        assert.contains(md, '**Test Run Comments (5 most recent)**');
