### js/common/linkedIssuesReport.js

```js
/**
 * Shared pure helpers for the linked-issue fetchers (fetchLinkedTestsToInput.js,
 * fetchLinkedBugsToInput.js). Extracted so both fetchers build identical
 * queries/comment blocks from one implementation (gh-1038).
 */

/**
 * Resolve the input folder context from the action params.
 * Accepts both the direct params shape ({ inputFolderPath }) and the
 * jobParams-wrapped shape ({ jobParams: { inputFolderPath }).
 * @returns {{actualParams: Object, folder: string, ticketKey: string}}
 */
function resolveInputContext(params) {
   var actualParams = params.inputFolderPath ? params : (params.jobParams || params);
   var folder = actualParams.inputFolderPath;
   return {
       actualParams: actualParams,
       folder: folder,
       ticketKey: folder.split('/').pop()
   };
}

/**
 * Build the provider query (JQL / WIQL pasthrough) for issues linked to a ticket.
 */
function buildLinkedQuery(ticketKey, typeFilter) {
   return 'issue in linkedIssues("' + ticketKey + '") AND ' + typeFilter;
}

/**
 * Render the most recent comments (up to 5) as markdown lines.
 * @param {Array} comments - comment objects with author.displayName / body
 * @param {string} headerPrefix - e.g. '**Test Run Comments' or '**Comments'
 * @returns {Array} markdown lines (empty when there are no comments)
 */
function buildRecentCommentLines(coments, headerPrefix) {
   var lines = [];
   if (!comments || comments.length === 0) {
       return lines;
   }
   var startIdx = Math.max(0, comments.length - 5);
   lines.push(headerPrefix + ' (' + (comments.length - startIdx) + ' most recent)**:\n');
   for (var j = startIdx; j < comments.length; j++) {
       var c = comments[j];
       var author = (c.author && c.author.displayName) || 'Unknown';
       var body = (c.body || '').substring(0, 200);
       lines.push('**[' + author + ']**:');
       lines.push(body);
       lines.push('');
   }
   return lines;
}

if (typeof module !== 'undefined' && module.exports) {
   module.exports = { resolveInputContext: resolveInputContext, buildLinkedQuery: buildLinkedQuery, buildRecentCommentLines: buildRecentCommentLines };
}
```

