        var env = makeBugsMocks({
            searchResult: [bugIssue('BUG-1', 'A', 'Open')],
            issueDetails: { 'BUG-1': bugIssue('BUG-1', 'A') }
        });
        var mod = loadFetchLinkedBugs(env.mocks);

