                'TC-2': jiraIssue('TC-2', 'Logout works', 'Failed', { comment: { comments: [] } })
            }
        });
        var mod = loadFetchLinkedTests(env.mocks);

        mod.action({ inputFolderPath: 'input/PROJ-7', jobParams: { customParams: {} } });

        assert.equal(env.written.length, 1);
